package com.atom.lib.frontend.contract;

import java.util.*;
import org.junit.jupiter.api.Test;
import static com.atom.lib.frontend.contract.ContractDesign.*;
import static org.junit.jupiter.api.Assertions.*;

class ContractSoundSessionTest {
    static ContractRegistry registry(boolean silent){return registry(silent,false);}
    static ContractRegistry registry(boolean silent,boolean conditional){var d=DesignResolverTest.fixture();var families=new HashMap<>(d.families());families.put("sound",new Family("root",Aspect.SOUND,"",Map.of("silent",silent?new SoundValue("FOCUS","","","",1,0,null,"reference input focus is silent"):new SoundValue("BUTTON","button","MASTER","volume",1,0,new NamedCondition.State("enabled"),""))));
        var roles=new HashMap<>(d.roles());if(conditional){var requirements=new EnumMap<Aspect,Requirement>(roles.get("action").requirements());requirements.put(Aspect.SOUND,Requirement.conditional(new NamedCondition.State("hover")));roles.put("action",new Role(true,requirements));}
        var sound=new ContractDesign(d.format(),d.namespace(),d.version(),d.profile(),d.scopes(),d.states(),Map.of("volume",new Parameter(0,1,.6,Unit.RATIO)),families,roles,d.recipes(),d.layouts(),Map.of("button",new Asset(AssetKind.SOUND,"example:feedback_button","reference resource")),d.pages());byte[] b=ContractCodec.encode(sound);return ContractRegistry.load(b,ContractRegistry.manifest(b,b),Set.of("example/1"));}
    static final class Sink implements UiSoundSink {final List<UiSoundIntent> outputs=new ArrayList<>();boolean present=true;public boolean supports(String channel){return channel.equals("MASTER");}public boolean available(String resource){return present;}public void play(UiSoundIntent value){outputs.add(value);}}
    @Test void committedActionProducesOneActualSinkOutputWithContractParameters(){var page=registry(false).page("settings");var recipe=page.recipe("card");var sink=new Sink();var sounds=new ContractSoundSession(page,sink);sounds.begin(1,1000);sounds.request(recipe,"BUTTON",Map.of("volume",.4),Map.of("enabled",true));sounds.request(recipe,"BUTTON",Map.of("volume",.4),Map.of("enabled",true));assertTrue(sink.outputs.isEmpty());assertEquals(ContractSoundSession.Result.PLAYED,sounds.end());assertEquals(List.of(new UiSoundIntent("BUTTON","example:feedback_button","MASTER",.4f,1,1,1000)),sink.outputs);}
    @Test void cancellationDisabledAndExplicitSilenceProduceNoOutput(){var page=registry(false).page("settings");var sink=new Sink();var sounds=new ContractSoundSession(page,sink);var r=page.recipe("card");sounds.begin(1,1000);sounds.request(r,"BUTTON",Map.of(),Map.of("enabled",true));sounds.cancel();assertTrue(sink.outputs.isEmpty());sounds.begin(2,1016);sounds.request(r,"BUTTON",Map.of(),Map.of("enabled",false));assertEquals(ContractSoundSession.Result.SILENT,sounds.end());var silent=registry(true).page("settings");var silentSounds=new ContractSoundSession(silent,sink);silentSounds.begin(3,1032);silentSounds.request(silent.recipe("card"),"FOCUS",Map.of(),Map.of());assertEquals(ContractSoundSession.Result.SILENT,silentSounds.end());assertTrue(sink.outputs.isEmpty());}
    @Test void missingResourceIsObservableAndDuplicateActionCannotReplay(){var page=registry(false).page("settings");var sink=new Sink();sink.present=false;var sounds=new ContractSoundSession(page,sink);sounds.begin(1,1000);sounds.request(page.recipe("card"),"BUTTON",Map.of(),Map.of("enabled",true));assertEquals(ContractSoundSession.Result.RESOURCE_UNAVAILABLE,sounds.end());assertTrue(sink.outputs.isEmpty());assertThrows(IllegalStateException.class,()->sounds.begin(1,1000));}
    @Test void directHostSoundRequestCannotBypassTheRoleCondition(){var page=registry(false,true).page("settings");var sink=new Sink();var session=new ContractSoundSession(page,sink);session.begin(1,1000);session.request(page.recipe("card"),"BUTTON",Map.of(),Map.of("enabled",true,"hover",false));assertEquals(ContractSoundSession.Result.SILENT,session.end());assertTrue(sink.outputs.isEmpty());session.begin(2,1016);session.request(page.recipe("card"),"BUTTON",Map.of(),Map.of("enabled",true,"hover",true));assertEquals(ContractSoundSession.Result.PLAYED,session.end());assertEquals(1,sink.outputs.size());}
}
